        try { await applyCommand({ type: 'add_pedal', part_index: address.part, staff_index: address.staff, measure_index: address.measure, voice: address.voice, start_note_idx: pedalStart.note, end_note_idx: address.note }, 'AddPedal'); pedalStart = null; } catch (error) { uiAlert(`ペダルを変更できませんでした: ${userFacingError(error)}`); }
