function groupScoreMetaControls() {
  const meta = $('score-meta');
  if (!meta || meta.querySelector('.meta-groups')) return;
  const groups = {
    Score: ['time-select', 'key-select', 'add-measure-button', 'delete-measure-button'],
    Notation: ['lyric-button', 'chord-button', 'rehearsal-button', 'measure-tempo-button', 'repeat-start-button', 'repeat-end-button', 'navigation-button', 'volta-button', 'expression-button', 'cue-button', 'note-head-button', 'fingering-button', 'string-number-button', 'technique-button', 'arpeggio-button', 'trill-button', 'technique-text-button', 'ottava-kind', 'ottava-button', 'stem-button'],
    Parts: ['part-select', 'staff-select', 'part-view-button', 'add-part-button', 'delete-part-button', 'add-staff-button', 'delete-staff-button', 'rename-part-button', 'export-part-button', 'export-part-midi-button', 'part-group-button'],
    Layout: ['multi-rest-button', 'page-break-button', 'system-break-button'],
    Playback: ['pedal-button', 'midi-input-select', 'midi-input-button', 'midi-input-status']
  };
  const grouped = new Set(Object.values(groups).flat());
  const container = document.createElement('div'); container.className = 'meta-groups';
  Object.entries(groups).forEach(([label, ids]) => { const elements = ids.map((id) => $(id)).filter(Boolean); if (!elements.length) return; const details = document.createElement('details'); details.className = `meta-group meta-group-${label.toLowerCase()}`; if (label === 'Score') details.open = true; const summary = document.createElement('summary'); summary.textContent = label; details.append(summary, ...elements); container.append(details); });
  const extra = [...meta.children].filter((element) => !grouped.has(element.id) && !['project-title', 'project-summary', 'tempo-display', 'settings-button'].includes(element.id));
  if (extra.length) { const details = document.createElement('details'); details.className = 'meta-group meta-group-more'; const summary = document.createElement('summary'); summary.textContent = 'More'; details.append(summary, ...extra); container.append(details); }
  const settings = $('settings-button'); meta.append(container); if (settings) meta.append(settings);
}
